begin;
set local role service_role;
do $$
declare administrator uuid; planner uuid; operator uuid; op uuid; customer uuid; result jsonb; item uuid; day uuid; event uuid; count_before bigint; denied boolean;
begin
  select id into administrator from crm_users where active and role='admin' limit 1;
  select id into planner from crm_users where active and role='planner' limit 1;
  operator:=crm_manage_account(administrator,'create',null,jsonb_build_object('username','qa_service_operator','display_name','计调事务测试','role','operations','password_salt',repeat('a',64),'password_hash',repeat('b',128)));
  perform crm_change_own_password(operator,repeat('b',128),repeat('c',64),repeat('d',128));
  select id,customer_id into op,customer from operation_cases limit 1;
  update operation_cases set start_date=(now() at time zone 'Asia/Shanghai')::date,end_date=(now() at time zone 'Asia/Shanghai')::date where id=op;
  select count(*) into count_before from operation_change_events where case_id=op;
  result:=crm_mutate_operation(planner,op,'operation_days',null,null,jsonb_build_object('day_number',999,'service_date',(now() at time zone 'Asia/Shanghai')::date,'city','测试'),false);
  day:=(result->>'id')::uuid;
  result:=crm_mutate_operation(planner,op,'operation_service_items',null,null,jsonb_build_object('day_id',day,'section','daily','category','guide','title','事务测试导游','quantity',1,'unit','项','booking_status','pending','invoice_unit_cost',500,'customer_unit_quote',700),false);
  item:=(result->>'id')::uuid;
  select id into event from operation_change_events where entity_id=item order by created_at desc limit 1;
  if not exists(select 1 from operation_change_events where id=event and actor_user_id=planner and strong_alert and new_value->>'title'='事务测试导游') then raise exception 'Audit missing actor/content/strong alert';end if;
  perform crm_mutate_operation(operator,op,'operation_service_items',item,0,'{"details":"计调协同编辑"}',false);
  denied:=false;
  begin perform crm_mutate_operation(planner,op,'operation_service_items',item,0,'{"details":"过期版本"}',false);exception when others then denied:=sqlerrm like 'CONFLICT:%';end;
  if not denied then raise exception 'Stale revision accepted';end if;
  if (select details from operation_service_items where id=item)<>'计调协同编辑' then raise exception 'Conflict overwrote content';end if;
  denied:=false;
  begin perform crm_acknowledge_operation_change(planner,customer,event,'operations',null);exception when insufficient_privilege then denied:=true;end;
  if not denied then raise exception 'Wrong role could acknowledge';end if;
  denied:=false;
  begin perform crm_acknowledge_operation_change(administrator,customer,event,'planner',null);exception when others then denied:=true;end;
  if not denied then raise exception 'Admin omitted substitute reason';end if;
  perform crm_acknowledge_operation_change(administrator,customer,event,'planner','代确认测试原因');
  if (select operations_ack_at is not null from operation_change_events where id=event) then raise exception 'One role closed both confirmations';end if;
  perform crm_acknowledge_operation_change(operator,customer,event,'operations',null);
  perform crm_acknowledge_operation_change(operator,customer,event,'operations',null);
  if (select count(*) from operation_change_acknowledgements where event_id=event)<>2 then raise exception 'Confirmation missing or duplicated';end if;
  for n in 1..125 loop
    perform crm_mutate_operation(planner,op,'operation_service_items',item,n,jsonb_build_object('details','测试历史 '||n),false);
  end loop;
  if (select count(*) from operation_change_events where case_id=op and strong_alert and (planner_ack_at is null or operations_ack_at is null))<125 then raise exception 'Open history truncated';end if;
  perform crm_mutate_operation(operator,op,'operation_service_items',item,126,'{}',true);
  if not exists(select 1 from operation_change_events where entity_id=item and action='deleted' and actor_user_id=operator and old_value->>'id'=item::text) then raise exception 'Deletion audit missing';end if;
  set local timezone='America/Los_Angeles';
  update operation_cases set start_date=(now() at time zone 'Asia/Shanghai')::date+1,end_date=(now() at time zone 'Asia/Shanghai')::date+2 where id=op;
  result:=crm_mutate_operation(planner,op,'operation_days',null,null,'{"day_number":1000,"city":"未来行程边界"}',false);
  if exists(select 1 from operation_change_events where entity_id=(result->>'id')::uuid and strong_alert) then raise exception 'Alert before Beijing start date';end if;
  update operation_cases set start_date=(now() at time zone 'Asia/Shanghai')::date-2,end_date=(now() at time zone 'Asia/Shanghai')::date-1 where id=op;
  result:=crm_mutate_operation(planner,op,'operation_days',null,null,'{"day_number":1001,"city":"已结束边界"}',false);
  if exists(select 1 from operation_change_events where entity_id=(result->>'id')::uuid and strong_alert) then raise exception 'Alert after Beijing end date';end if;
  update operation_cases set start_date=(now() at time zone 'Asia/Shanghai')::date,end_date=(now() at time zone 'Asia/Shanghai')::date where id=op;
  result:=crm_mutate_operation(planner,op,'operation_days',null,null,'{"day_number":1002,"city":"首尾同日边界"}',false);
  if not exists(select 1 from operation_change_events where entity_id=(result->>'id')::uuid and strong_alert and actor_user_id=planner) then raise exception 'Beijing inclusive boundary changed with session timezone';end if;
  raise notice 'PASS: transactional actor audit, optimistic conflict, collaborative roles, Beijing interval, admin reason, dual acknowledgements, >100 alerts and deletion';
end $$;
rollback;
